eval("module.exports = JSON.parse('{\"舌色\":{\"淡红舌\":\"红为血之色，明润光泽为胃气之华。淡红舌则说明心血充足、胃气旺盛。\",\"淡白舌\":\"气血亏虚，血不荣舌，或阳气虚衰，运血无力，不能温运血液上荣于舌，致舌色浅淡。\",\"绛舌\":\"绛舌多由红舌进一步发展而成。形成原因是热入营血，气血沸涌，耗伤营阴，血液浓缩；或虚火旺盛，上炎于舌络，血络充盈，故呈绛色。\",\"青紫舌\":\"由于气血运行不畅，故舌见青紫。青紫舌多由淡白舌或红绛舌发展而成，故其主病即是在淡白舌或红绛舌基础上出现气血运行不畅的病理改变。\",\"苍白舌\":\"白如枯骨无血色，较淡白舌更为严重。此舌多现于急症亡阳、大失血后，提示阳气暴脱或精血枯涸的危重证候。\",\"鲜红舌\":\"舌红似朱砂，表面如镜面反光。此为实热炽盛之象，常见于高热、感染性疾病，提示体内火毒壅滞。\",\"暗红舌\":\"舌色红中透暗，如隔雾观火。主瘀热内结或阴虚火旺，见于慢性炎症、肿瘤等病程，提示血行不畅与阴液耗损并存。\",\"瘀斑舌\":\"舌面现紫黑斑点，如露水珠痕。此属离经之血留滞，可能提示外伤、内出血或恶性肿瘤，需结合全身症状警惕器质性病变。\"},\"舌形\":{\"老舌\":\"舌质老、嫩是疾病虚实的标志之一。实邪亢盛，充斥体内，而正气未衰，邪正交争，邪气壅滞于上，故舌质苍老。\",\"嫩舌\":\"气血不足，舌体脉络不充，或阳气亏虚，运血无力，寒湿内生，以致舌嫩色淡白。\",\"胖大舌\":\"舌淡胖大者，多为脾肾阳虚，津液输布障碍，水湿之邪停滞于体内的表现。舌红胖大者，多属脾胃湿热或痰热相搏，湿热痰饮上泛所致。\",\"肿胀舌\":\"舌肿胀色红绛，其成因主要有心脾热盛，热毒上壅；或素嗜饮酒，又病温热，邪热夹酒毒上壅；或因中毒导致血液瘀滞。此外，先天性舌血管瘤患者，可因舌局部血络瘀闭，呈现青紫肿胀。\",\"瘦薄舌\":\"瘦薄舌总由气血阴液不足，不能充盈舌体，舌失濡养所致。舌体瘦薄而色淡者，多是气血两虚；舌体瘦薄红绛，舌干少苔或无苔者，多见于阴虚火旺。\",\"点刺舌\":\"点是由蕈状乳头增生，数目增多，充血肿大而形成。刺是蕈状乳头增大高突，形成尖峰，形如芒刺。舌生点刺是邪热炽盛，充斥舌络所致，一般点刺愈多，邪热愈甚。\",\"裂纹舌\":\"1.舌红绛而有裂纹，多属热盛伤阴。因邪热内盛，阴液大伤，或阴虚液损，使舌体失于濡润，舌面萎缩所致。2.舌淡白而有裂纹，多为血虚不润。因血虚不能上荣于舌，舌体失养，故见裂纹。3.舌淡白胖嫩，边有齿痕又兼见裂纹者，则多属脾虚湿侵。因脾失健运，湿邪内侵，则舌胖嫩有齿痕；精微不能上输濡养舌体，则舌淡而见裂纹。4.若生来舌面上就有较浅的裂沟、裂纹，裂纹中一般有苔覆盖，且无不适感觉者，称为先天性舌裂，应与病理性裂纹加以鉴别。\",\"齿痕舌\":\"舌边有齿痕，多因舌体胖大而受牙齿挤压所致，故多与胖大舌同见；亦有舌体不大而呈现齿痕者，是舌质较嫩的齿痕舌。\"},\"苔质\":{\"薄苔\":\"舌苔薄白而均匀，或中部稍厚，干湿适中，为正常舌苔，提示胃有生发之气；若在病中，说明病情轻浅，未伤胃气。\",\"厚苔\":\"厚苔是由胃气兼夹湿浊、痰浊、食浊等熏蒸，积滞舌面所致，说明疾病在里，病情较重。\",\"润苔\":\"润苔是正常舌苔的表现之一，是胃津、肾液上承，濡润舌面的表现。疾病过程中见润苔，提示体内津液未伤，如风寒表证、湿证初起、食滞、瘀血等均可见润苔。\",\"燥苔\":\"燥苔提示体内津液已伤，如邪热炽盛，大汗、吐泻后，或过服温燥药物等，导致津液不足，舌苔失于濡润而干燥；亦有因痰饮、瘀血内阻，阳气被遏，津液输布障碍而不能上承舌面而见燥苔。\",\"腻苔\":\"腻苔多由湿浊内蕴，阳气被遏，湿浊、痰饮停聚舌面所致。舌苔厚腻，多为湿浊、痰饮、食积。\",\"腐苔\":\"腐苔的形成，多因阳热有余，蒸腾胃中秽浊之邪上泛，聚积舌面，主食积胃肠，或痰浊内蕴。\",\"剥（落）苔\":\"剥（落）苔的形成，总因胃气匮乏，不得上熏于舌，或胃阴损伤，不能上潮于舌所致。由于导致胃气、胃阴亏损的原因不同，损伤的程度亦有轻重，因而形成各种类型的剥脱苔。\"},\"苔色\":{\"白苔\":\"白苔为舌苔之本色，是最常见的苔色，其他苔色均可由白苔转化而成。苔薄白而润，可为正常舌象，或表证初起，或里证病轻，或阳虚内寒。\",\"黄苔\":\"邪热熏灼于舌，故苔呈黄色。一般情况下，苔色愈黄，说明热邪愈甚，浅黄苔为热轻，深黄苔为热重，焦黄苔为热结。\",\"灰黑苔\":\"1.灰黑苔可见于热性病中，亦可见于寒湿病中，但无论寒、热均属重证，黑色越深，病情越重。2.亦有苔灰黑而无明显症状者，如吸烟过多者，是为染苔。\"},\"津液\":{\"润\":\"津液未伤，上承正常\",\"滑\":\"寒湿、痰饮内生，聚于舌面而成滑苔\",\"燥\":\"热盛伤津或津液输布障碍\"},\"舌下络脉\":{\"正常舌脉\":\"舌下络脉为舌体血络所聚，正常时隐隐可见\",\"舌脉粗长如网\":\"血瘀则舌下络脉增粗增长，颜色深红或紫暗；痰浊、热毒内蕴，则舌下络脉扩张\",\"舌脉曲张\":\"血瘀较重则舌下络脉曲张明显；气滞则血瘀，亦可见舌下络脉曲张\",\"舌脉瘀血\":\"血瘀则舌下络脉中可见瘀血点或瘀血块；外伤损伤舌下络脉，亦可导致瘀血\"}}');\n\n//# sourceURL=webpack://hsop/./src/service/result.json?");

